 "code": "rlm.harness.create_memory(title='ARC overlay blank intersection recoloring', content='Task pattern: Grid has two noisy rectangular panels separated by a full row/column of a distinct separator color. Panels share dimensions. Top panel uses foreground F and background B; bottom panel uses foreground G and the same background B. Produce panel-sized output: retain B everywhere except recolor to 3 those positions where BOTH corresponding panel cells equal B. In demos, inputs used upper (9 foreground, 4 background), lower (5 foreground, 4 background), separator 8; output was 3 exactly at coincident background 4 cells and 4 elsewhere. In solved test, upper used foreground 9/background 7, lower foreground 5/background 7; output was 3 at coincident 7/7 positions and 7 elsewhere. Keep original panel background, not fixed color. Common pitfall: submit requires object {\"action\":\"submit\",\"grid\":...}, and default cells retain original background (not arbitrary filler). Panels were stacked vertically, with separator row, output same width and height as either panel.",
 "id": "arc_overlay_background_intersection",
 "global_": true,
 "path": "arc"
}
